contents.plugin.json:
{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "sill",
  "version": "1.1.3",
  "description": "查看、整理和管理你的云端卡片。",
  "author": {
    "name": "Sill"
  },
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "Sill",
        "shortDescription": "查看、整理和管理你的云端卡片。",
        "longDescription": "Sill · 窗台。东西在光里，安放一会儿。通过应用、侧边栏和技能管理同一份云端卡片。",
        "developerName": "Sill",
        "category": "Productivity",
        "capabilities": [
          "Interactive"
        ],
        "defaultPrompt": [
          "在侧边栏打开 Sill",
          "查看我的 Sill 云端卡片"
        ],
        "logo": "./assets/sill-icon.png",
        "composerIcon": "./assets/sill-line.svg",
        "composerIconDark": "./assets/sill-line-dark.svg"
      },
      "requires_local_executor": false,
      "apps": "./.app.json"
    }
  }
}
